(function(root){'use strict';
function entries(items){const tasks=items.filter(n=>!n.deletedAt&&n.type==='task').flatMap(n=>(n.tasks||[]).filter(t=>!t.done&&t.id&&t.notification&&(t.notification.ongoing||t.notification.when>0)).map(t=>({id:n.id+':'+t.id,itemId:n.id,rev:t.notification.rev,when:t.notification.when||0,ongoing:!!t.notification.ongoing,title:n.title.slice(0,120),body:t.text.slice(0,1000)})));return tasks.concat(items.filter(n=>!n.deletedAt&&n.persistentNotice).map(n=>({id:n.id+':notice:pinned',itemId:n.id,kind:'item',rev:n.persistentNotice.rev,when:0,ongoing:true,title:n.title.slice(0,120),body:n.capsule?.sealed?'A sealed Time Capsule':(n.type==='task'?(n.tasks||[]).map(t=>(t.done?'✓ ':'☐ ')+t.text).join('\n'):n.transcript||n.caption||String(n.html||'').replace(/<[^>]*>/g,' ').replace(/&(?:amp|lt|gt|quot|#39);/g,s=>({'&amp;':'&','&lt;':'<','&gt;':'>','&quot;':'"','&#39;':"'"}[s])).replace(/\s+/g,' ').trim()).slice(0,1000)})),items.filter(n=>!n.deletedAt&&n.capsule?.sealed&&n.capsule.notify).map(n=>({id:n.id+':capsule',itemId:n.id,rev:n.capsule.rev||n.capsule.unlockAt,when:n.capsule.unlockAt,ongoing:false,title:'Your time capsule is ready',body:n.title.slice(0,120)})));}
function merge(items,actions){for(const n of items){if(n.deletedAt)continue;if(n.persistentNotice){const a=actions.find(a=>a.id===n.id+':notice:pinned'&&a.rev===n.persistentNotice.rev);if(a&&['complete','stop'].includes(a.action))delete n.persistentNotice;}if(n.capsule){const action=actions.find(a=>a.id===n.id+':capsule'&&a.rev===(n.capsule.rev||n.capsule.unlockAt));if(action&&['complete','stop'].includes(action.action)){n.capsule.notify=false;n.capsule.notifiedAt=Date.now();}}if(n.type!=='task')continue;for(const t of n.tasks||[]){const a=actions.find(a=>a.id===n.id+':'+t.id&&a.rev===t.notification?.rev);if(!a)continue;if(a.action==='complete')t.done=true;if(['complete','stop'].includes(a.action))delete t.notification;}}}
const api={entries,merge};if(typeof module!=='undefined')module.exports=api;else root.NotaTasks=api;
})(typeof window!=='undefined'?window:globalThis);
